dispatch_args.command_text:
$ErrorActionPreference='SilentlyContinue'
[Console]::OutputEncoding=New-Object Text.UTF8Encoding $false
$OutputEncoding=New-Object Text.UTF8Encoding $false
$path='C:/Users/limone/AppData/Local/PADIEM/MeshCentralTrial/notes.txt'
$offset=[int64]0
$length=[int64]16
$items=Get-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
if($items -eq $null -or $items.PSIsContainer){
  '{"ok":false,"error":"not_a_file"}'
  return
}
$guardRoot='C:\Users\limone\AppData\Local\PADIEM\MeshCentralTrial\'
$guardHit=$null
try{
  $walk=$guardRoot
  foreach($seg in ('notes.txt'.Replace('\','/') -split '/')){
    if(-not $seg){continue}
    $walk=Join-Path $walk $seg
    if(-not (Test-Path -LiteralPath $walk)){break}
    $item=Get-Item -LiteralPath $walk -Force -ErrorAction SilentlyContinue
    if($item -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)){$guardHit=$walk;break}
  }
}catch{$guardHit=$guardRoot}
if($guardHit){
  '{"ok":false,"error":"link_refused","message":"이 위치는 바로가기 폴더를 거쳐서 읽을 수 없습니다."}'
  return
}
$size=[int64]$items.Length
if($offset -gt $size){
  '{"ok":false,"error":"offset_out_of_range","size_bytes":' + $size + '}'
  return
}
$fs=[IO.File]::OpenRead($path)
$want=[int][Math]::Min($length+3,$size-$offset)
$buf=New-Object byte[] $want
[void]$fs.Seek($offset,[IO.SeekOrigin]::Begin)
[void]$fs.Read($buf,0,$want)
$fs.Close()
$start=0
while($start -lt $want -and ($buf[$start] -band 0xC0) -eq 0x80 -and $start -lt 3){ $start++ }
$n=$want-$start
$cut=0
if($n -ge 0){
  $i=0
  while($i -lt $n){
    $b=$buf[$start+$i]
    $need=1
    if(($b -band 0xE0) -eq 0xC0){ $need=2 }
    elseif(($b -band 0xF0) -eq 0xE0){ $need=3 }
    elseif(($b -band 0xF8) -eq 0xF0){ $need=4 }
    if($i+$need -gt $n){ break }
    $i=$i+$need
  }
  $cut=$i
}
if($cut -le 0){
  '{"ok":false,"error":"no_complete_character","size_bytes":' + $size + '}'
  return
}
$text=[Text.Encoding]::UTF8.GetString($buf,$start,$cut)
$next=$offset+$start+$cut
$eof=($next -ge $size)
if($text.IndexOf([char]0) -ge 0){
  '{"ok":false,"error":"binary_text_rejected","size_bytes":' + $size + '}'
  return
}
[ordered]@{ok=$true;unit='bytes';size_bytes=$size;offset=$offset;length_bytes=($start+$cut);next_offset=$next;eof=$eof;text=$text} | ConvertTo-Json -Compress -Depth 4

$ErrorActionPreference='SilentlyContinue'
[Console]::OutputEncoding=New-Object Text.UTF8Encoding $false
$OutputEncoding=New-Object Text.UTF8Encoding $false
$query=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('dGVzdA=='))
$mode='name'
$limit=50
$scan=2000
$maxOffice=8
$prefix=[int64]16777216
$roots=@(@{label=([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('TWVzaENlbnRyYWxUcmlhbA==')));path=([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('QzovVXNlcnMvbGltb25lL0FwcERhdGEvTG9jYWwvUEFESUVNL01lc2hDZW50cmFsVHJpYWw=')))})
$multi=($roots.Count -gt 1)
$office=@('.docx','.xlsx','.pdf','.hwpx')
$officeMedia=@{'.docx'='application/vnd.openxmlformats-officedocument.wordprocessingml.document';'.xlsx'='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';'.pdf'='application/pdf';'.hwpx'='application/hwp+zip'}
$textExt=@('.txt','.md','.csv','.log','.json','.xml','.yml','.yaml','.html','.css','.js','.ts','.py','.ps1','.sql','.ini','.cfg','.bat','.sh')
$offlineMask=4096 -bor 4194304
$rows=New-Object System.Collections.ArrayList
$flags=@{truncated=$false;scan=$false;engine='list';office='none';time=$false}
$sw=[Diagnostics.Stopwatch]::StartNew()
$timeLimit=180
$progressFile=$null
$lastProgress=[datetime]::MinValue
function Test-Time {
  if($sw.Elapsed.TotalSeconds -ge $timeLimit){ $flags.time=$true; return $true }
  if($null -ne $progressFile -and $sw.Elapsed.TotalSeconds - $lastProgress.TotalSeconds -ge 15){
    try { Set-Content -LiteralPath $progressFile -Value ([datetime]::UtcNow.ToString('o')) -Encoding ascii } catch { }
    $lastProgress=[datetime]::UtcNow
  }
  return $false
}
function Add-Row([object]$item,[string]$label,[string]$kind,[object]$line,[string]$text,[string]$reason,[string]$base,[object]$byteOffset){
  if($rows.Count -ge $limit){ $flags.truncated=$true; return }
  $rel=$item.FullName.Substring($base.Length).TrimStart([char]92,[char]47)
  if($multi){ $rel=$label + '/' + $rel }
  [void]$rows.Add([ordered]@{path=$rel;size_bytes=[int64]$item.Length;modified_utc=$item.LastWriteTimeUtc.ToString('o');content_state=$kind;line=$line;snippet=$text;reason=$reason;byte_offset=$byteOffset})
}
if($mode -eq 'name'){
  $es=Get-Command es.exe -ErrorAction SilentlyContinue | Select-Object -First 1
  if($es -and -not $query.StartsWith('-')){
    $flags.engine='everything'
    foreach($r in $roots){
      $hits=@(& $es.Source -path $r.path -n ($limit+1) $query)
      foreach($p in $hits){
        if($rows.Count -ge $limit){ $flags.truncated=$true; break }
        $full=([string]$p).Replace('/','\')
        if(-not $full){ continue }
        if(-not $full.StartsWith($r.path.Replace('/','\'),[StringComparison]::OrdinalIgnoreCase)){ continue }
        $i=Get-Item -LiteralPath $full -Force -ErrorAction SilentlyContinue
        if($i -eq $null){ continue }
        $off=(($i.Attributes -band $offlineMask) -ne 0)
        Add-Row $i $r.label $(if($off){'not_downloaded'}else{'name_only'}) $null '' '' $r.path $null
      }
    }
  } else {
    foreach($r in $roots){
      $seen=0
      foreach($i in (Get-ChildItem -LiteralPath $r.path -Recurse -Force -ErrorAction SilentlyContinue)){
        $seen++
        if($seen -gt $scan){ $flags.scan=$true; break }
        if($rows.Count -ge $limit){ $flags.truncated=$true; break }
        if(Test-Time){ $flags.truncated=$true; break }
        $nameC=$i.Name.Normalize([Text.NormalizationForm]::FormC)
        if($nameC.IndexOf($query,[StringComparison]::OrdinalIgnoreCase) -lt 0){ continue }
        $off=(($i.Attributes -band $offlineMask) -ne 0)
        Add-Row $i $r.label $(if($off){'not_downloaded'}else{'name_only'}) $null '' '' $r.path $null
      }
    }
  }
}
if($mode -eq 'content'){
  $texts=New-Object System.Collections.ArrayList
  $byPath=@{}
  $offices=New-Object System.Collections.ArrayList
  foreach($r in $roots){
    $seen=0
    foreach($i in (Get-ChildItem -LiteralPath $r.path -Recurse -File -Force -ErrorAction SilentlyContinue)){
      $seen++
      if($seen -gt $scan){ $flags.scan=$true; break }
      if($rows.Count -ge $limit){ $flags.truncated=$true; break }
      if(Test-Time){ $flags.truncated=$true; break }
      $ext=$i.Extension.ToLowerInvariant()
      $nameHit=($i.Name.Normalize([Text.NormalizationForm]::FormC).IndexOf($query,[StringComparison]::OrdinalIgnoreCase) -ge 0)
      $off=(($i.Attributes -band $offlineMask) -ne 0)
      if($off){
        if($nameHit){ Add-Row $i $r.label 'not_downloaded' $null '' '' $r.path } $null
        continue
      }
      if($office -contains $ext){
        [void]$offices.Add([pscustomobject]@{item=$i;label=$r.label;root=$r.path;type=$officeMedia[$ext]})
        continue
      }
      if($textExt -contains $ext){
        $entry=[pscustomobject]@{item=$i;label=$r.label;root=$r.path}
        [void]$texts.Add($entry)
        $byPath[$i.FullName]=$entry
        continue
      }
      if($nameHit){ Add-Row $i $r.label 'name_only' $null '' '' $r.path } $null
    }
  }
  $rg=Get-Command rg.exe -ErrorAction SilentlyContinue | Select-Object -First 1
  if($texts.Count -gt 0 -and $rg){
    $flags.engine='ripgrep'
    for($start=0; $start -lt $texts.Count; $start+=100){
      if($rows.Count -ge $limit){ $flags.truncated=$true; break }
      $end=[Math]::Min($start+99,$texts.Count-1)
      $paths=@()
      for($n=$start;$n -le $end;$n++){ $paths+=$texts[$n].item.FullName }
      $hits=@(& $rg.Source -H --no-heading --line-number --byte-offset --color never --no-messages --fixed-strings --max-count 1 -- $query $paths)
      foreach($line in $hits){
        if($rows.Count -ge $limit){ $flags.truncated=$true; break }
        if($line -match '^(.*?):(\d+):(\d+):(.*)$'){
          $snippet=$matches[4].Trim()
          if($snippet.Length -gt 200){ $snippet=$snippet.Substring(0,200) }
          $entry=$byPath[$matches[1]]
          if($entry -eq $null){ continue }
          Add-Row $entry.item $entry.label 'matched' ([int]$matches[2]) $snippet '' $entry.root ([int64]$matches[3])
        }
      }
    }
  } elseif($texts.Count -gt 0){
    $flags.engine='select-string'
    foreach($f in $texts){
      if($rows.Count -ge $limit){ $flags.truncated=$true; break }
      $hit=Select-String -LiteralPath $f.item.FullName -SimpleMatch -Pattern $query -List -ErrorAction SilentlyContinue | Select-Object -First 1
      if($hit){
        $snippet=$hit.Line.Trim()
        if($snippet.Length -gt 200){ $snippet=$snippet.Substring(0,200) }
        Add-Row $f.item $f.label 'matched' $hit.LineNumber $snippet '' $f.root $null
      }
    }
  }
  if($offices.Count -gt 0){
    $py=Get-Command python -ErrorAction SilentlyContinue | Select-Object -First 1
    $parser=$false
    if($py){
      $probe=@('{ }' | & $py.Source -P -m kagent.document_parser_child 2>$null)
      try { $parser=((($probe -join '') | ConvertFrom-Json).ok -eq $false) } catch { $parser=$false }
    }
    if($parser){ $flags.office='parser' } else { $flags.office='unavailable' }
    $opened=0
    foreach($o in $offices){
      if($rows.Count -ge $limit){ $flags.truncated=$true; break }
      $nameHit=($o.item.Name.Normalize([Text.NormalizationForm]::FormC).IndexOf($query,[StringComparison]::OrdinalIgnoreCase) -ge 0)
      if(-not $parser){
        if($nameHit){ Add-Row $o.item $o.label 'deferred' $null '' 'extractor_unavailable' $o.root } $null
        continue
      }
      if($opened -ge $maxOffice){
        if($nameHit){ Add-Row $o.item $o.label 'deferred' $null '' 'office_cap' $o.root } $null
        else { $flags.truncated=$true }
        continue
      }
      $opened++
      $fs=[IO.File]::OpenRead($o.item.FullName)
      $len=[int][Math]::Min($fs.Length,$prefix)
      $buf=New-Object byte[] $len
      [void]$fs.Read($buf,0,$len)
      $fs.Close()
      $partial=([int64]$o.item.Length -gt [int64]$len)
      $envelope=@{name=$o.item.Name;media_type=$o.type;base64=[Convert]::ToBase64String($buf)} | ConvertTo-Json -Compress
      $report=@($envelope | & $py.Source -P -m kagent.document_parser_child 2>$null)
      $parsed=$null
      try { $parsed=(($report -join '') | ConvertFrom-Json) } catch { $parsed=$null }
      if($parsed -ne $null -and $parsed.ok -eq $true -and $parsed.text -is [string]){
        $idx=$parsed.text.IndexOf($query,[StringComparison]::OrdinalIgnoreCase)
        if($idx -ge 0){
          $startText=$parsed.text.LastIndexOf([char]10,$idx)+1
          $endText=$parsed.text.IndexOf([char]10,$idx)
          if($endText -lt 0){ $endText=$parsed.text.Length }
          $lineText=$parsed.text.Substring($startText,$endText-$startText).Trim()
          if($lineText.Length -gt 200){ $lineText=$lineText.Substring(0,200) }
          Add-Row $o.item $o.label 'matched' $null $lineText $(if($partial){'prefix_only'}else{''}) $o.root $null
        } elseif($nameHit){
          Add-Row $o.item $o.label 'name_only' $null '' '' $o.root $null
        }
      } elseif($partial){
        Add-Row $o.item $o.label 'partial' $null '' 'prefix_only' $o.root $null
      } elseif($nameHit){
        $code=if($parsed -ne $null -and $parsed.code){ ([string]$parsed.code -replace '[^a-z0-9_]','') } else { 'read_failed' }
        if($code.Length -gt 40){ $code=$code.Substring(0,40) }
        Add-Row $o.item $o.label 'deferred' $null '' $code $o.root $null
      }
    }
  }
}
[ordered]@{ok=$true;mode=$mode;query=$query;engine=$($flags.engine);office=$($flags.office);count=$($rows.Count);truncated=$($flags.truncated);time_truncated=$($flags.time);scan_truncated=$($flags.scan);entries=$rows} | ConvertTo-Json -Compress -Depth 5
